#!/bin/sh
# SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0
#
# Inject the NVIDIA SPDX header into generated Go files (idempotent).
#
# mockery / mockgen (GoMock) and controller-gen (`zz_generated.deepcopy.go`) emit
# no license header, so their output is header-less. The generate make targets
# (`generate-mocks` / `generate-mocks-client` for mockery; `generate-mockgen` for
# GoMock; the CRD `generate` targets for controller-gen) run this immediately
# after the generator, so every regenerated file carries the header (do not
# hand-stamp — regen would wipe it). Also usable standalone to backfill:
#
#   sh build/makefile/scripts/spdx-header-go.sh <dir>   # default <dir> = .
#
# Scope: gated on the generated MARKER ("Code generated by mockery / MockGen /
# controller-gen"), NOT on the path — so it works whatever directory the
# generator writes to (e.g. mockery's scattered `<pkg>/mocks/`, mockgen's
# `internal/autogenerate/mocks/`, the `temp-mocks/` drift dir, and each CRD
# api group's `zz_generated.deepcopy.go`). Hand-written code lacks the marker and
# is left alone; vendored trees (`/vendor/`, `/third_party/`, `/thirdpartyapi/`,
# `/goofys/`) are pruned by path; and — defense-in-depth for the controller-gen
# case — any file whose preamble carries a NAMED foreign copyright (e.g. the
# kubebuilder default "Copyright The Kubernetes Authors", "The Kubeflow Authors")
# is skipped so we never stamp NVIDIA over someone else's attribution. Already-
# headered files are skipped (idempotent).
set -eu

H1='// SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.'
H2='// SPDX-License-Identifier: Apache-2.0'

root="${1:-.}"

find "$root" -type f -name '*.go' 2>/dev/null \
	| grep -vE '/vendor/|/third_party/|/thirdpartyapi/|/goofys/' \
	| while IFS= read -r f; do
	# Only generated files (marker may sit below a //go:build line, so scan a
	# small window, not just line 1).
	head -n 6 "$f" | grep -qE 'Code generated by (mockery|MockGen|controller-gen)' || continue
	# Skip anything already headered (idempotent).
	head -n 6 "$f" | grep -q 'SPDX-FileCopyrightText' && continue
	# Do-no-harm: never stamp over a named foreign copyright (e.g. a controller-gen
	# tree scaffolded with the kubebuilder default boilerplate). Those get their
	# header fixed generator-side (boilerplate.go.txt), not by us.
	FOREIGN='Copyright.*(Authors|Inc\.|, Inc| LLC|Kubernetes|Kubeflow|Google|Microsoft|Seldon|KServe)|Licensed under the Apache License'
	head -n 8 "$f" | grep -qiE "$FOREIGN" && continue
	# A zz_generated file is bare but inherits its package's provenance: if a
	# sibling type file in the same dir is third-party (vendored CRD, e.g. the
	# Kubeflow mpijob/v2beta1 types), skip the whole package.
	case "$f" in
	*zz_generated*.go)
		# portable: BSD/macOS `head` has no -q, so read each sibling individually
		if for s in "$(dirname "$f")"/*.go; do [ -f "$s" ] && head -n 8 "$s"; done \
			2>/dev/null | grep -qiE "$FOREIGN"; then
			continue
		fi
		;;
	esac
	tmp="${f}.spdxtmp.$$"
	# Place the header after any leading Go build-constraint lines and the single
	# blank line that follows them; for header-less mocks (no build tag) it goes at
	# the very top. Matches the already-headered zz_generated/mocks siblings.
	awk -v h1="$H1" -v h2="$H2" '
		BEGIN { inpre = 1; had_build = 0; done = 0 }
		inpre && ($0 ~ /^\/\/go:build/ || $0 ~ /^\/\/ \+build/) { print; had_build = 1; next }
		inpre && had_build && $0 == "" { print ""; print h1; print h2; print ""; inpre = 0; done = 1; next }
		inpre { inpre = 0; if (!done) { print h1; print h2; print ""; done = 1 } print; next }
		{ print }
	' "$f" > "$tmp" && mv "$tmp" "$f"
done
